def parse_ga4_row(row,dim_headers,metric_headers):
  out={}
  for i,h in enumerate(dim_headers): out[h['name']]=row['dimensionValues'][i]['value']
  for i,h in enumerate(metric_headers):
    v=row['metricValues'][i]['value'];t=h.get('type')
    out[h['name']]=int(v) if t=='TYPE_INTEGER' else float(v) if t in ('TYPE_FLOAT','TYPE_SECONDS') else v
  return out
